mod tests{
 use super::*;
 use std::io::Write;
 #[test]
 fn sqlite_snapshot_architect_core_and_first_registers_match_independent_sqlite(){
  let original:serde_json::Value=serde_json::from_str(include_str!("../../../🧫️fixtures/🧬️mutations/👥️stakeholder/🌱️create/🌱️creates-a/📸️snapshot/➡️after/🔣️.json")).unwrap();
  let mut snapshot:super::super::ProgramSnapshot=semio_framework_pack_json::from_json_str(&original.to_string(), semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();snapshot.stakeholders[0].header.name="世界\0__proto__".into();snapshot.stakeholders.push(snapshot.stakeholders[0].clone());
  let mut callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut callback,store::sqlite_snapshot::SqliteDatabaseLimits::default());let mut p=Projection::new(SCHEMA,&mut control).unwrap();project_core(&snapshot,&mut p).unwrap();register_project(&mut p,&snapshot.stakeholders).unwrap();register_project(&mut p,&snapshot.users).unwrap();register_project(&mut p,&snapshot.activities).unwrap();register_project(&mut p,&snapshot.functions).unwrap();register_project(&mut p,&snapshot.elements).unwrap();let database=p.finish().unwrap();
  let bytes=store::sqlite_snapshot::export_sqlite_database(&database,store::sqlite_snapshot::SqliteDatabaseLimits::default(),&mut |_|true).unwrap();
  let script=r#"import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));console.log(JSON.stringify({title:d.query('SELECT title FROM architect_meta').get().title,names:d.query('SELECT name FROM architect_entity_header ORDER BY ordinal').all().map(r=>r.name),violations:d.query('PRAGMA foreign_key_check').all()}));"#;
