mod tests{
 use super::*;
 use std::io::Write;
 #[test]
 fn sqlite_snapshot_architect_core_and_first_registers_match_independent_sqlite(){
  let original:serde_json::Value=serde_json::from_str(include_str!("../../../🧫️fixtures/🧬️mutations/👥️stakeholder/🌱️create/🌱️creates-a/📸️snapshot/➡️after/🔣️.json")).unwrap();
  let mut snapshot:super::super::ProgramSnapshot=semio_framework_pack_json::from_json_str(&original.to_string(), semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();snapshot.stakeholders[0].header.name="世界\0__proto__".into();snapshot.stakeholders.push(snapshot.stakeholders[0].clone());
  let mut callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut callback,store::sqlite_snapshot::SqliteDatabaseLimits::default());let mut p=RowWriter::new(SCHEMA,&mut control).unwrap();project_core(&snapshot,&mut p).unwrap();register_project(&mut p,&snapshot.stakeholders).unwrap();register_project(&mut p,&snapshot.users).unwrap();register_project(&mut p,&snapshot.activities).unwrap();register_project(&mut p,&snapshot.functions).unwrap();register_project(&mut p,&snapshot.elements).unwrap();let database=p.finish().unwrap();
  let bytes=store::sqlite_snapshot::export_sqlite_database(&database,store::sqlite_snapshot::SqliteDatabaseLimits::default(),&mut |_|true).unwrap();
  let script=r#"import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));console.log(JSON.stringify({title:d.query('SELECT title FROM architect_meta').get().title,names:d.query('SELECT name FROM architect_entity_header ORDER BY ordinal').all().map(r=>r.name),violations:d.query('PRAGMA foreign_key_check').all()}));"#;
  let mut child=std::process::Command::new("bun").args(["--eval",script]).stdin(std::process::Stdio::piped()).stdout(std::process::Stdio::piped()).stderr(std::process::Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let oracle:serde_json::Value=serde_json::from_slice(&output.stdout).unwrap();assert_eq!(oracle["title"],snapshot.meta.title);assert_eq!(oracle["names"],serde_json::json!(["世界\0__proto__","世界\0__proto__"]));assert_eq!(oracle["violations"],serde_json::json!([]));
  let database=store::sqlite_snapshot::import_sqlite_database(&bytes,store::sqlite_snapshot::SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let mut permit=|_|true;let mut native=semio_framework_value::NativeDecodeControl::new(8_000_000,&mut permit);let mut r=Reader::new(&database,&mut native).unwrap();let root=r.singleton("architect_document",2).unwrap();assert_eq!(root.text(1).unwrap(),snapshot.schema);assert_eq!(read_meta(&mut r).unwrap(),snapshot.meta);assert_eq!(read_project(&mut r).unwrap(),snapshot.project);assert_eq!(read_governance(&mut r).unwrap(),snapshot.governance);assert_eq!(read_child::<semio_s_artifact_stdio_semio::standards::v1::subsets::table::schema::snapshot::SemioTableSnapshot>(&mut r,"knowledge").unwrap(),snapshot.knowledge);assert_eq!(read_child::<semio_s_artifact_stdio_semio::standards::v1::subsets::table::schema::snapshot::SemioTableSnapshot>(&mut r,"benchmarks").unwrap(),snapshot.benchmarks);assert_eq!(r.list::<TraceLink>("architect_trace",1).unwrap(),snapshot.traces);assert_eq!(register_restore::<Stakeholder>(&mut r).unwrap(),snapshot.stakeholders);assert_eq!(register_restore::<UserProfile>(&mut r).unwrap(),snapshot.users);assert_eq!(register_restore::<Activity>(&mut r).unwrap(),snapshot.activities);assert_eq!(register_restore::<Function>(&mut r).unwrap(),snapshot.functions);assert_eq!(register_restore::<ProgramElement>(&mut r).unwrap(),snapshot.elements);r.finish().unwrap();
 }
